const PREFIX = 'hanja-shell-';
const CACHE_NAME = PREFIX + CACHE_VERSION;
const META_CACHE = 'hanja-meta';
const FETCH_TIMEOUT_MS = 60000;
const VERSION_TIMEOUT_MS = 5000;
const CONCURRENCY = 6;
const RETRY_MS = 24 * 60 * 60 * 1000;
const MANIFEST_KEY = '__manifest__';
const IS_DEV = CACHE_VERSION.indexOf('__') === 0;

const SCOPE = self.registration.scope;
const SCOPE_PATH = new URL(SCOPE).pathname;

function absolute(rel) {
  return new URL(rel, SCOPE).href;
}

async function fetchFresh(url, timeoutMs) {
  const ctrl = new AbortController();
  const timer = setTimeout(() => ctrl.abort(), timeoutMs);
  try {
    // 브라우저 HTTP 캐시의 옛 파일이 새 버전 캐시에 섞이지 않게 항상 새로 받는다.
    const res = await fetch(url, { cache: 'reload', signal: ctrl.signal });
    if (!res.ok) throw new Error('HTTP ' + res.status + ' ' + url);
    return res;
  } finally {
    clearTimeout(timer);
  }
}

function failureReason(err) {
  if (err && err.name === 'QuotaExceededError') return 'quota';
  if (err && err.name === 'AbortError') return 'timeout';
  if (err && /^HTTP /.test(String(err.message))) return 'http';
  return 'network';
}

// 같은 버전의 설치가 24시간 안에 실패했으면 다시 받지 않고 바로 실패시킨다.
async function recentlyFailed() {
  const meta = await caches.open(META_CACHE);
  const hit = await meta.match(absolute('__install_failed__'));
  if (!hit) return false;
  const data = await hit.json();
  return data.version === CACHE_VERSION && Date.now() - data.at < RETRY_MS;
}

async function notifyFailure(reason) {
  try {
    const meta = await caches.open(META_CACHE);
    await meta.put(
      absolute('__install_failed__'),
      new Response(JSON.stringify({ version: CACHE_VERSION, at: Date.now() })),
    );
  } catch (_) {}
  const clients = await self.clients.matchAll({ type: 'window', includeUncontrolled: true });
  for (const c of clients) {
    c.postMessage({ type: 'install-failed', reason, update: !!self.registration.active });
  }
}

// 이전 버전 캐시들과 파일별 해시 표(__manifest__). 설치를 끝낸 캐시만 표가 있다.
async function previousCaches() {
  const out = [];
  for (const name of await caches.keys()) {
    if (!name.startsWith(PREFIX) || name === CACHE_NAME) continue;
    const cache = await caches.open(name);
    const m = await cache.match(absolute(MANIFEST_KEY));
    if (m) out.push({ cache, hashes: await m.json() });
  }
  return out;
}

async function precache() {
  if (await recentlyFailed()) throw new Error('recent failure');
  const cache = await caches.open(CACHE_NAME);
  const previous = await previousCaches();
  let next = 0;
  let failed = false;
  async function worker() {
    while (!failed && next < PRECACHE.length) {
      const [rel, hash] = PRECACHE[next++];
      const url = absolute(rel);
      try {
        let reused = null;
        for (const p of previous) {
          if (p.hashes[rel] !== hash) continue;
          reused = await p.cache.match(url);
          if (reused) break;
        }
        await cache.put(url, reused || (await fetchFresh(url, FETCH_TIMEOUT_MS)));
      } catch (err) {
        failed = true;
        throw err;
      }
    }
  }
  try {
    await Promise.all(Array.from({ length: CONCURRENCY }, worker));
    const stored = await cache.keys();
    if (stored.length < PRECACHE.length) throw new Error('incomplete cache');
    const hashes = {};
    for (const [rel, hash] of PRECACHE) hashes[rel] = hash;
    await cache.put(absolute(MANIFEST_KEY), new Response(JSON.stringify(hashes)));
  } catch (err) {
    await caches.delete(CACHE_NAME);
    await notifyFailure(failureReason(err));
    throw err;
  }
}

self.addEventListener('install', (event) => {
  if (IS_DEV) return;
  event.waitUntil(precache());
});

self.addEventListener('activate', (event) => {
  if (IS_DEV) return;
  event.waitUntil(
    (async () => {
      for (const name of await caches.keys()) {
        if (name.startsWith(PREFIX) && name !== CACHE_NAME) await caches.delete(name);
      }
    })(),
  );
});

// 오디오 등 Range 요청에 캐시 본문으로 206을 만들어 준다(Safari는 200 응답을 거부한다).
async function rangeResponse(request, hit) {
  const m = /^bytes=(\d*)-(\d*)$/.exec(request.headers.get('range') || '');
  // 여러 구간·해석 못 하는 Range는 캐시로 흉내 내지 않고 네트워크에 맡긴다.
  if (!m || (m[1] === '' && m[2] === '')) return fetch(request);
  const buf = await hit.arrayBuffer();
  const size = buf.byteLength;
  let start;
  let end;
  if (m[1] === '') {
    start = Math.max(0, size - Number(m[2]));
    end = size - 1;
  } else {
    start = Number(m[1]);
    end = m[2] === '' ? size - 1 : Math.min(Number(m[2]), size - 1);
  }
  if (start >= size || start > end) {
    return new Response(null, { status: 416, headers: { 'Content-Range': 'bytes */' + size } });
  }
  return new Response(buf.slice(start, end + 1), {
    status: 206,
    headers: {
      'Content-Type': hit.headers.get('Content-Type') || 'application/octet-stream',
      'Content-Range': 'bytes ' + start + '-' + end + '/' + size,
      'Content-Length': String(end - start + 1),
      'Accept-Ranges': 'bytes',
    },
  });
}

async function shellResponse(request, rel) {
  const cache = await caches.open(CACHE_NAME);
  const isNav = request.mode === 'navigate';
  const key = isNav && (rel === '' || rel === 'index.html') ? absolute('index.html') : request;
  const hit = await cache.match(key, { ignoreSearch: true });
  if (hit) return request.headers.has('range') ? rangeResponse(request, hit) : hit;
  return fetch(request);
}

async function versionResponse(request) {
  const key = absolute('version.json');
  const meta = await caches.open(META_CACHE);
  const ctrl = new AbortController();
  const timer = setTimeout(() => ctrl.abort(), VERSION_TIMEOUT_MS);
  try {
    const res = await fetch(request, { cache: 'no-store', signal: ctrl.signal });
    if (res.ok) await meta.put(key, res.clone());
    return res;
  } catch (_) {
    const hit = await meta.match(key);
    return hit || new Response('', { status: 504, statusText: 'offline' });
  } finally {
    clearTimeout(timer);
  }
}

self.addEventListener('fetch', (event) => {
  const request = event.request;
  if (IS_DEV || request.method !== 'GET') return;
  const url = new URL(request.url);
  if (url.origin !== location.origin || !url.pathname.startsWith(SCOPE_PATH)) return;
  if (url.searchParams.get('nosw') === '1') return;
  const rel = url.pathname.slice(SCOPE_PATH.length);
  if (rel === 'sw.js') return;
  if (rel === 'version.json') {
    event.respondWith(versionResponse(request));
    return;
  }
  event.respondWith(shellResponse(request, rel));
});

// 페이지가 "지금 켜진 버전이 오프라인 준비가 끝난 것인가"를 물을 때 답한다.
self.addEventListener('message', (event) => {
  if (!event.data || event.data.type !== 'status' || !event.ports[0]) return;
  event.ports[0].postMessage({ version: CACHE_VERSION, dev: IS_DEV });
});
